package android.os; import java.util.*; public class PersistableBundle { final Map<String,String> m=new HashMap<>(); public PersistableBundle(){} public PersistableBundle(PersistableBundle x){m.putAll(x.m);} public void putString(String k,String v){m.put(k,v);} public String getString(String k){return m.get(k);} public String getString(String k,String d){return m.containsKey(k)?m.get(k):d;} }
